def encode_zorp(value):
    if isinstance(value, int):
        if value < 0:
            return f"#{value * -1}"
        else:
            return f"#{value}"
    elif isinstance(value, str):
        return f"~{value}~"
    elif isinstance(value, list):
        encoded_elements = []
        for item in value:
            if isinstance(item, int):
                if item < 0:
                    encoded_elements.append(f"#{item * -1}")
                else:
                    encoded_elements.append(f"#{item}")
            elif isinstance(item, str):
                encoded_elements.append(f"~{item}~")
            elif isinstance(item, list):
                # Recursively encode nested lists
                encoded_elements.append(encode_zorp(item))
        return f"<{';'.join(encoded_elements)}>"
    else:
        # Handle other types if needed
        return str(value)
